    return text, ''
def first_def_name(s):
    m_ = re.search(r'def\s+([A-Za-z_][A-Za-z0-9_]*)\s*\(', s)
    return (m_.group(1), m_.start()) if m_ else (None, None)
def rename_origin(r_):
    ep_ = ep_of[r_['id']]; th_, an_ = split_answer(r_['text'])
    cds = code_defs(r_['code']); var_ = [d_ for d_ in cds if d_ != ep_]
    var_ = max(var_, key=lambda d_: (d_.lower() == ep_.lower(), d_.startswith(ep_))) if var_ else None
    fd_, pos_ = first_def_name(th_)
    if var_ is None: return 'nodef', fd_, var_
    pre_ = th_[:pos_] if pos_ is not None else th_
    if var_ in pre_: return 'prose-before-def', fd_, var_
    if fd_ == var_: return 'first-think-def', fd_, var_
    if fd_ is None: return 'code-only(no think def)', fd_, var_
    if fd_ == ep_: return 'think-ok,code-renamed', fd_, var_
